/* Шрифты для картинок-карточек (Manrope латиница+кириллица, Noto Sans Georgian, знак лари ₾ из Noto Sans), формат woff в base64. Сгенерировано из @fontsource. */
import "server-only";

const RAW: [string, 500 | 800, string][] = [
  ["M", 500, ""],
  ["M", 800, ""],
  ["MC", 500, ""],
  ["MC", 800, ""],
  ["G", 500, ""],
  ["G", 800, ""],
  ["S", 500, ""],
  ["S", 800, ""],
];

let cache: { name: string; data: ArrayBuffer; weight: 500 | 800; style: "normal" }[] | null = null;

export function cardFonts() {
  if (!cache) cache = RAW.map(([name, weight, b]) => { const buf = Buffer.from(b, "base64"); return { name, weight, style: "normal" as const, data: buf.buffer.slice(buf.byteOffset, buf.byteOffset + buf.byteLength) as ArrayBuffer }; });
  return cache;
}
